package ec2

import (
	"fmt"

	"github.com/truvity/asg"
)

const (
	iamVersion = "2012-10-17"
)

// instanceStatements are the statements of the instance role that are the
// box's own: the replica prefix of the bucket and, if one is given, the one KMS
// key. The rest of the role's policy is generated by github.com/truvity/asg
// from what the user-data and the modules read: ssm:GetParameter on exactly
// the parameter names, s3:GetObject on exactly the object keys, the two Auto
// Scaling actions on the box's own group, and the self-registration's
// sts:AssumeRole on exactly its role. There is no managed policy on the role
// unless SessionManager asks for one: AmazonSSMManagedInstanceCore would let it
// read every parameter in the account.
func (a Args) instanceStatements() []asg.Statement {
	objects := fmt.Sprintf("arn:%s:s3:::%s/*", partition, a.Bucket)
	listPrefix := "*"

	if a.BucketPrefix != "" {
		objects = fmt.Sprintf("arn:%s:s3:::%s/%s/*", partition, a.Bucket, a.BucketPrefix)
		listPrefix = a.BucketPrefix + "/*"
	}

	statements := []asg.Statement{
		{
			Sid:      "ReplicaObjects",
			Effect:   "Allow",
			Action:   []string{"s3:GetObject", "s3:PutObject", "s3:DeleteObject"},
			Resource: []string{objects},
		},
		{
			Sid:       "ReplicaList",
			Effect:    "Allow",
			Action:    []string{"s3:ListBucket"},
			Resource:  []string{"arn:" + partition + ":s3:::" + a.Bucket},
			Condition: map[string]map[string][]string{"StringLike": {"s3:prefix": {listPrefix}}},
		},
		{
			Sid:      "ReplicaRegion",
			Effect:   "Allow",
			Action:   []string{"s3:GetBucketLocation"},
			Resource: []string{"arn:" + partition + ":s3:::" + a.Bucket},
		},
	}

	if a.KMSKeyARN != "" {
		statements = append(statements, asg.Statement{
			Sid:      "OwnKey",
			Effect:   "Allow",
			Action:   []string{"kms:Decrypt", "kms:GenerateDataKey"},
			Resource: []string{a.KMSKeyARN},
		})
	}

	return statements
}
